const input = $json.body ?? $json;

const text = (value) => {
  if (value === null || value === undefined) return '';
  return String(value).trim();
};

const toBoolean = (value) => {
  if (typeof value === 'boolean') return value;
  return ['true', '1', 'yes', 'on'].includes(text(value).toLowerCase());
};

const session_id = Number(input.session_id);
const message_id = Number(input.message_id);
const webhook_base_url = text(
  input.webhook_base_url || 'http://localhost:5678/webhook'
).replace(/\/+$/, '');
const allow_retry = toBoolean(input.allow_retry);
const max_retry_attempts = Number(input.max_retry_attempts ?? 3);
const confirm_execution = toBoolean(input.confirm_execution);

const errors = [];

if (!Number.isInteger(session_id) || session_id < 1) {
  errors.push({
    field: 'session_id',
    message: 'session_id باید یک عدد صحیح بزرگ‌تر از صفر باشد.',
  });
}

if (!Number.isInteger(message_id) || message_id < 1) {
  errors.push({
    field: 'message_id',
    message: 'message_id باید یک عدد صحیح بزرگ‌تر از صفر باشد.',
  });
}

if (!/^https?:\/\/.+/i.test(webhook_base_url)) {
  errors.push({
    field: 'webhook_base_url',
    message: 'آدرس پایه Webhook معتبر نیست.',
  });
}

if (
  !Number.isInteger(max_retry_attempts) ||
  max_retry_attempts < 1 ||
  max_retry_attempts > 10
) {
  errors.push({
    field: 'max_retry_attempts',
    message: 'حداکثر تعداد تلاش باید بین 1 و 10 باشد.',
  });
}

if (confirm_execution !== true) {
  errors.push({
    field: 'confirm_execution',
    message: 'اجرای ابزار باید به‌صورت صریح تأیید شود.',
  });
}

return [{
  json: {
    session_id,
    message_id,
    webhook_base_url,
    allow_retry,
    max_retry_attempts,
    confirm_execution,
    validation_status: errors.length === 0 ? 'valid' : 'invalid',
    errors,
  },
}];

if ($json.success !== true) {
  return [{ json: $json }];
}

const input = $('Normalize and Validate Tool Execution').first().json;
const context = $json.execution_context || {};
const routing = context.routing_payload || {};

const endpoint = String(routing.endpoint || '')
  .trim()
  .replace(/^\/+/, '');

const method = String(routing.method || 'POST')
  .trim()
  .toUpperCase();

if (
  !endpoint ||
  endpoint.includes('..') ||
  endpoint.includes('://') ||
  !/^[a-zA-Z0-9/_-]+$/.test(endpoint)
) {
  throw new Error('Stored tool route contains an unsafe endpoint.');
}

if (!['POST'].includes(method)) {
  throw new Error('Stored tool route uses an unsupported HTTP method.');
}

const toolPayload =
  routing.payload &&
  typeof routing.payload === 'object' &&
  !Array.isArray(routing.payload)
    ? routing.payload
    : {};

const executionUrl =
  `${input.webhook_base_url}/${endpoint}`;

return [{
  json: {
    success: true,
    result: 'tool_execution_prepared',
    session_id: Number(context.session_id),
    message_id: Number(context.message_id),
    clinic_id: Number(context.clinic_id),
    clinic_name: context.clinic_name,
    safe_tool_action:
      routing.safe_tool_action ||
      context.tool_action ||
      'none',
    target_workflow_number:
      routing.target_workflow_number ?? null,
    target_workflow_name:
      routing.target_workflow_name ?? null,
    endpoint,
    method,
    tool_payload: toolPayload,
    tool_payload_json: JSON.stringify(toolPayload),
    execution_url: executionUrl,
    allow_retry: input.allow_retry,
    max_retry_attempts: input.max_retry_attempts,
    execution_started_at_ms: Date.now(),
  },
}];

const request = $('Prepare Tool Execution Request').first().json;
const reservation = $('Reserve Tool Execution').first().json;
const raw = $json ?? {};

const statusCode = Number(
  raw.statusCode ??
  raw.status ??
  raw.httpStatus ??
  0
);

let responseBody =
  raw.body !== undefined
    ? raw.body
    : (
        raw.data !== undefined
          ? raw.data
          : raw
      );

if (typeof responseBody === 'string') {
  try {
    responseBody = JSON.parse(responseBody);
  } catch {
    responseBody = {
      text: responseBody,
    };
  }
}

const connectionError =
  raw.error !== undefined ||
  raw.name === 'NodeApiError' ||
  raw.name === 'NodeOperationError';

const successfulStatus =
  statusCode === 0 ||
  (statusCode >= 200 && statusCode < 300);

const toolReportedFailure =
  responseBody &&
  typeof responseBody === 'object' &&
  responseBody.success === false;

const success =
  !connectionError &&
  successfulStatus &&
  !toolReportedFailure;

const errorMessage = success
  ? null
  : String(
      raw.message ||
      raw.error?.message ||
      responseBody?.message ||
      responseBody?.error ||
      `Tool execution failed with HTTP status ${statusCode || 'unknown'}`
    ).slice(0, 4000);

return [{
  json: {
    success,
    result: success
      ? 'routed_tool_executed'
      : 'routed_tool_failed',
    execution_log_id:
      Number(reservation.execution_log_id),
    session_id: request.session_id,
    message_id: request.message_id,
    safe_tool_action: request.safe_tool_action,
    target_workflow_number:
      request.target_workflow_number,
    target_workflow_name:
      request.target_workflow_name,
    endpoint: request.endpoint,
    execution_url: request.execution_url,
    http_status: statusCode || null,
    response_payload: responseBody,
    response_payload_json:
      JSON.stringify(responseBody ?? {}),
    error_type: success
      ? null
      : (
          connectionError
            ? 'connection_or_node_error'
            : (
                toolReportedFailure
                  ? 'tool_reported_failure'
                  : 'http_error'
              )
        ),
    error_message: errorMessage,
    duration_ms: Math.max(
      0,
      Date.now() -
        Number(
          request.execution_started_at_ms ||
          Date.now()
        )
    ),
  },
}];

return [{
  json: {
    success: false,
    result: 'invalid_request',
    message: 'اطلاعات لازم برای اجرای ابزار ناقص یا نامعتبر است.',
    errors: $json.errors ?? [],
  },
}];

return [{
  json: {
    success: false,
    result: $json.result || 'tool_execution_context_not_available',
    message:
      $json.result === 'tool_route_not_found'
        ? 'ابتدا Workflow شماره 53 را اجرا کنید.'
        : (
            $json.result === 'tool_route_not_ready'
              ? 'مسیر ابزار هنوز آماده اجرا نیست.'
              : 'پیام یا جلسه مکالمه پیدا نشد.'
          ),
  },
}];
